import re
from datetime import timedelta
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

BUILTIN = {
    "max_size": None,
    "max_age": None,
    "naming": "numbered",
    "offset": timedelta(0),
    "compress_after": 1,
    "keep": 5,
    "keep_days": None,
}

_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_DURATION = re.compile(r"([0-9]+)([mhd])\Z")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_WHOLE = re.compile(r"[0-9]+\Z")
_UNITS = {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}
_SPANS = {"m": timedelta(minutes=1), "h": timedelta(hours=1), "d": timedelta(days=1)}


def _bad(message):
    return DataError("policy", f"policy.ini: {message}")


def _off(parse):
    def wrapper(value):
        return None if value == "off" else parse(value)

    return wrapper


def _size(value):
    match = _SIZE.match(value)
    if not match:
        raise ValueError(value)
    return int(match.group(1)) * _UNITS[match.group(2).lower()]


def _duration(value):
    match = _DURATION.match(value)
    if not match:
        raise ValueError(value)
    return int(match.group(1)) * _SPANS[match.group(2)]


def _naming(value):
    if value not in ("numbered", "dated"):
        raise ValueError(value)
    return value


def _offset(value):
    match = _OFFSET.match(value)
    if not match:
        raise ValueError(value)
    hours, minutes = int(match.group(2)), int(match.group(3))
    if hours > 23 or minutes > 59:
        raise ValueError(value)
    delta = timedelta(hours=hours, minutes=minutes)
    return -delta if match.group(1) == "-" else delta


def _whole(minimum):
    def parse(value):
        if not _WHOLE.match(value) or int(value) < minimum:
            raise ValueError(value)
        return int(value)

    return parse


_PARSERS = {
    "max_size": _off(_size),
    "max_age": _off(_duration),
    "naming": _naming,
    "offset": _offset,
    "compress_after": _whole(0),
    "keep": _whole(1),
    "keep_days": _off(_whole(1)),
}


class Policy:
    def __init__(self, defaults=None, sections=None):
        self.defaults = defaults or {}
        self.sections = sections or {}

    def stream_names(self):
        return set(self.sections)

    def settings(self, name):
        out = dict(BUILTIN)
        out.update(self.defaults)
        out.update(self.sections.get(name, {}))
        return out


def load(path: Path) -> Policy:
    if not path.exists():
        return Policy()
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise _bad(str(e)) from None
    defaults = None
    sections = {}
    current = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                raise _bad(f"bad section line: {line}")
            title = line[1:-1]
            if title == "defaults":
                if defaults is not None:
                    raise _bad("section [defaults] given twice")
                defaults = current = {}
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in sections:
                    raise _bad(f"section [{title}] given twice")
                sections[name] = current = {}
            else:
                raise _bad(f"unknown section [{title}]")
            continue
        if current is None or "=" not in line:
            raise _bad(f"bad line: {line}")
        key, value = (part.strip() for part in line.split("=", 1))
        if key not in _PARSERS:
            raise _bad(f"unknown key {key}")
        if key in current:
            raise _bad(f"key {key} given twice")
        try:
            current[key] = _PARSERS[key](value)
        except ValueError:
            raise _bad(f"bad value for {key}: {value}") from None
    return Policy(defaults, sections)
