import re
from datetime import datetime, timedelta, timezone

from logkeep import dates, policy as policy_module, state, streams
from logkeep.errors import DataError, Refused

_TIME = re.compile(
    r"([0-9]{4})-([0-9]{2})-([0-9]{2})T([0-9]{2}):([0-9]{2}):([0-9]{2})(?:\.([0-9]+))?(Z|[+-][0-9]{2}:[0-9]{2})\Z"
)
_OLD_TIME = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")
_DAY = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})\Z")
_NUMBER = re.compile(r"[1-9][0-9]*\Z")


def parse_time(text, allow_old=False):
    """A datetime, or None when text is not a time of docs/data.md, section 2."""
    if not isinstance(text, str):
        return None
    try:
        if allow_old and _OLD_TIME.match(text):
            return datetime.strptime(text, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
        match = _TIME.match(text)
        if not match:
            return None
        year, month, day, hour, minute, second = (int(match.group(i)) for i in range(1, 7))
        micro = int((match.group(7) or "0")[:6].ljust(6, "0"))
        zone = match.group(8)
        if zone == "Z":
            tz = timezone.utc
        else:
            hours, minutes = int(zone[1:3]), int(zone[4:6])
            if hours > 23 or minutes > 59:
                return None
            delta = timedelta(hours=hours, minutes=minutes)
            tz = timezone(-delta if zone[0] == "-" else delta)
        return datetime(year, month, day, hour, minute, second, micro, tzinfo=tz)
    except ValueError:
        return None


def _state_time(text):
    return parse_time(text, allow_old=True)


class Archive:
    def __init__(self, name, key, gz):
        self.name = name
        self.key = key
        self.gz = gz
        self.new = False
        self.time = None
        self.content = None


def _base(stream, naming):
    return re.escape(f"{stream}.log.")


def find_archives(logs_dir, stream, naming):
    found = {}
    if not logs_dir.is_dir():
        return []
    if naming == "numbered":
        pattern = re.compile(re.escape(f"{stream}.log.") + r"([1-9][0-9]*)(\.gz)?\Z")
    else:
        pattern = re.compile(
            re.escape(f"{stream}.log.") + r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z"
        )
