    removed_lines = [line.replace("  remove", "remove", 1) for line in removed_lines]
    return {
        "name": name,
        "what": what,
        "rotated": rotated,
        "kept": kept,
        "removed": [item for item in removed if not item.new],
        "lines": [f"{name}: {_label(what)}"] + lines + removed_lines,
        "compressed": compressed,
    }


