    return f"rotate ({what})" if what in ("forced", "size", "age") else what


def run(ctx, names, dry_run, force):
    ctx.force = force
    policy = policy_module.load(ctx.policy_path)
    doc = ctx.state
    existing = existing_streams(ctx, policy)
    check_state(doc, existing)
